        c = b.new_context(viewport={'width': 390, 'height': 844}, timezone_id='Europe/Chisinau', service_workers='block'); pgx = c.new_page()
        pgx.route('**/rest/v1/**', fake); pgx.goto(URL); pgx.wait_for_timeout(1800)
